package check

import (
	"fmt"
	"slices"
	"strings"

	"ergo.local/prototype/internal/sketch/syntax"
)

// C→Ergo callbacks and statically checked scoped C borrows (CFFI-3 / bind-c-7).
//
// A C binding generated by `ergo bind c` binds both call-scoped (`ScopeCall`)
// and registered (`ScopeRegistered`) callbacks:
//   - ScopeCall callbacks are non-escaping (`func(...) R fails CE needs CR`)
//     with row polymorphism on the enclosing C function (`fails CE | go.Error
//     needs CR | go.Foreign`). Any C-borrowed `in_buffer` slice parameter of
//     the callback is marked above the declaration with:
//       // ergo:scoped <cbParam>.<sliceParam>
//   - ScopeRegistered callbacks are escaping (`own func(...) R`) with empty
//     fails and needs rows, so Ergo's escape/row checker refuses capturing a
//     `with`-bound capability (S102) or frame-local borrow (S108).
//
// Every `// ergo:scoped` slice parameter (and any local alias or sub-slice of
// it) is enforced by an allow-list in escWalk:
//   - Never captured by an escaping frame (S108).
//   - Never returned, stored in a record/tuple/slice/Option/outer `let mut`,
//     appended to an outer slice, mutated via index write, or passed to an
//     unverified/`own` parameter (S108).
//   - Allowed only in read-only indexing, sub-slicing (tracked as scoped),
//     `len`/`.Len()`, `for ... in`, `copy(dst, src)`, `slices.Clone`/`bytes.Clone`/`.Clone()`,
//     immutable local aliasing (`let y = data`), and `// ergo:reads` parameters.

const (
	scopedMarker = "// ergo:scoped "
	cbTypeMarker = "// ergo:cbtype "

	scopedCaptureText = "%s is a C-borrowed scoped slice (// ergo:scoped) and cannot be captured by an escaping function literal or block; copy it with slices.Clone first"
	scopedEscapeText  = "%s is a C-borrowed scoped slice (// ergo:scoped) valid only during the C callback: it may only be indexed, sliced locally, measured with len, iterated, cloned with slices.Clone, or passed to a // ergo:reads parameter — never returned, stored, mutated, or passed where it may escape"
	scopedMutText     = "%s cannot be declared let mut with a C-borrowed scoped slice (// ergo:scoped); bind it with let or copy it with slices.Clone"
)

type cScopedSpec struct {
	cbParam    string
	sliceParam string
}

type cCbTypeSpec struct {
	cbParam string
	goType  string
}

// cbTypeLine records `// ergo:cbtype <cbParam> <GoTypeName>` above fn.
func (h *hostPkg) cbTypeLine(fn *Func, text string) {
	fields := strings.Fields(text)
	if len(fields) != 2 {
		h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:cbtype` line above %s must have the form `<callbackParam> <GoTypeName>`", fn.Name)
		return
	}
	if h.cbTypes == nil {
		h.cbTypes = map[*Func][]cCbTypeSpec{}
	}
	h.cbTypes[fn] = append(h.cbTypes[fn], cCbTypeSpec{cbParam: fields[0], goType: fields[1]})
}

// scopedLine records `// ergo:scoped cbParam.sliceParam ...` above fn.
func (h *hostPkg) scopedLine(fn *Func, text string) {
	fields := strings.Fields(text)
	if len(fields) == 0 {
		h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` line above %s names no callback slice parameter", fn.Name)
		return
	}
	for _, tok := range fields {
		cbName, sliceName, ok := strings.Cut(tok, ".")
		if !ok || cbName == "" || sliceName == "" || strings.Contains(sliceName, ".") {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` token %q above %s must have the form `<callbackParam>.<sliceParam>`", tok, fn.Name)
			continue
		}
		if h.scoped == nil {
			h.scoped = map[*Func][]cScopedSpec{}
		}
		h.scoped[fn] = append(h.scoped[fn], cScopedSpec{cbParam: cbName, sliceParam: sliceName})
	}
}

// verifyCBindScoped resolves every `// ergo:scoped` and `// ergo:cbtype` spec
// on fn against fn.Sig.
func (h *hostPkg) verifyCBindScoped(fn *Func) {
	if fn.Sig == nil {
		return
	}
	if specs := h.cbTypes[fn]; len(specs) > 0 {
		if h.cbTypeResolved == nil {
			h.cbTypeResolved = map[*Func]map[int]string{}
		}
		byIdx := map[int]string{}
		for _, sp := range specs {
			cbIdx := -1
			for i, p := range fn.Sig.Params {
				if p.Name == sp.cbParam {
					cbIdx = i
					break
				}
			}
			if cbIdx < 0 {
				h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:cbtype` line above %s names %s, which is not one of its parameters", fn.Name, sp.cbParam)
				continue
			}
			if _, ok := under0(fn.Sig.Params[cbIdx].Type).(*Signature); !ok {
				h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:cbtype` line above %s names %s, which is not a callback parameter", fn.Name, sp.cbParam)
				continue
			}
			byIdx[cbIdx] = h.c.pkg.Path + "." + sp.goType
		}
		if len(byIdx) > 0 {
			h.cbTypeResolved[fn] = byIdx
		}
	}
	specs := h.scoped[fn]
	if len(specs) == 0 {
		return
	}
	if h.scopedResolved == nil {
		h.scopedResolved = map[*Func]map[int]map[int]bool{}
	}
	byCb := map[int]map[int]bool{}
	for _, sp := range specs {
		cbIdx := -1
		for i, p := range fn.Sig.Params {
			if p.Name == sp.cbParam {
				cbIdx = i
				break
			}
		}
		if cbIdx < 0 {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` line above %s names %s, which is not one of its parameters", fn.Name, sp.cbParam)
			continue
		}
		cbSig, ok := under0(fn.Sig.Params[cbIdx].Type).(*Signature)
		if !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` line above %s names %s, which is not a callback parameter", fn.Name, sp.cbParam)
			continue
		}
		sliceIdx := -1
		for j, cp := range cbSig.Params {
			if cp.Name == sp.sliceParam {
				sliceIdx = j
				break
			}
		}
		if sliceIdx < 0 {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` line above %s names %s.%s, which is not a parameter of callback %s", fn.Name, sp.cbParam, sp.sliceParam, sp.cbParam)
			continue
		}
		sl, ok := cbSig.Params[sliceIdx].Type.(*Slice)
		if !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` line above %s names %s.%s (%s), which is not a slice parameter", fn.Name, sp.cbParam, sp.sliceParam, cbSig.Params[sliceIdx].Type)
			continue
		}
		if ok, why := h.c.isCData(sl.Elem); !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "the `// ergo:scoped` slice %s.%s element (%s) is not C-safe: %s", sp.cbParam, sp.sliceParam, sl.Elem, why)
			continue
		}
		if byCb[cbIdx] == nil {
			byCb[cbIdx] = map[int]bool{}
		}
		byCb[cbIdx][sliceIdx] = true
	}
	if len(byCb) > 0 {
		h.scopedResolved[fn] = byCb
	}
}

// verifyCBindCallbackParam checks that a callback parameter on a C-bound
// function has C-safe parameter/result types, declares `// ergo:scoped` for
// every C-borrowed slice parameter, and enforces ScopeRegistered lifetime rules.
func (h *hostPkg) verifyCBindCallbackParam(fn *Func, idx int, p *Var, cbSig *Signature) {
	scopedSet := h.scopedResolved[fn][idx]
	for j, cp := range cbSig.Params {
		if sl, ok := cp.Type.(*Slice); ok {
			if ok, why := h.c.isCData(sl.Elem); !ok {
				h.c.errorf(fn.Decl.Name, CodeType, "C binding %s callback %s parameter %s (%s) is not C-safe: %s", fn.Name, p.Name, cp.Name, cp.Type, why)
				continue
			}
			if !scopedSet[j] {
				h.c.errorf(fn.Decl.Name, CodeType, "C binding %s callback %s slice parameter %s must be annotated with // ergo:scoped %s.%s", fn.Name, p.Name, cp.Name, p.Name, cp.Name)
			}
			continue
		}
		if ok, why := h.c.isCData(cp.Type); !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s callback %s parameter %s (%s) is not C-safe: %s", fn.Name, p.Name, cp.Name, cp.Type, why)
		}
	}
	for _, cr := range cbSig.Results {
		if ok, why := h.c.isCData(cr); !ok {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s callback %s result (%s) is not C-safe: %s", fn.Name, p.Name, cr, why)
		}
	}
	// Escaping (`own func`) callbacks are ScopeRegistered: they outlive the call
	// and must not carry a fails row or capture a capability row.
	if !cbSig.NonEscaping {
		if cbSig.Fallible {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s registered callback %s (own func) cannot declare a fails row", fn.Name, p.Name)
		}
		if cbSig.Uses != nil && !cbSig.Uses.Empty() {
			h.c.errorf(fn.Decl.Name, CodeType, "C binding %s registered callback %s (own func) cannot declare a needs row", fn.Name, p.Name)
		}
	}
}

// IsCBindFunc reports whether f belongs to a `// ergo:bind c` host binding.
func IsCBindFunc(f *Func) bool {
	if f == nil || f.Pkg == nil {
		return false
	}
	h := hostOf(f.Pkg)
	return h != nil && h.cBind
}

// GoCallbackTypeName returns the package-qualified Go defined callback type
// name (e.g. "ergo.local/bind/fixture.WriteCallback") for callback parameter
// cbIdx of a C-bound function, or "".
func GoCallbackTypeName(f *Func, cbIdx int) string {
	if f == nil || f.Pkg == nil {
		return ""
	}
	h := hostOf(f.Pkg)
	if h == nil || !h.cBind {
		return ""
	}
	h.verifyCBindAll()
	h.mu.Lock()
	name := h.cbTypeResolved[f][cbIdx]
	h.mu.Unlock()
	return name
}

// GoScopedCallbackParams returns the set of parameter indices inside callback
// parameter cbIdx of f that are marked `// ergo:scoped`, or nil.
func GoScopedCallbackParams(f *Func, cbIdx int) map[int]bool {
	m := scopedCallbackMap(f)
	if m == nil {
		return nil
	}
	return m[cbIdx]
}

func scopedCallbackMap(f *Func) map[int]map[int]bool {
	if f == nil || f.Pkg == nil {
		return nil
	}
	h := hostOf(f.Pkg)
	if h == nil || !h.cBind {
		return nil
	}
	h.verifyCBindAll()
	h.mu.Lock()
	m := h.scopedResolved[f]
	h.mu.Unlock()
	return m
}

// collectScopedVars scans file f for calls to C-bound functions carrying
// `// ergo:scoped` callback parameters and records the callback parameter Vars
// that hold C-borrowed scoped slices.
func (w *escWalk) collectScopedVars(f *fileInfo) {
	w.scopedVars = map[*Var]string{}
	localLits := map[*Var]*syntax.FuncLit{}
	pkgDecls := map[*Func]*syntax.FuncDecl{}

	for _, d := range f.syntax.Decls {
		if fd, ok := d.(*syntax.FuncDecl); ok && fd.Body != nil {
			if fn, ok := w.info.Defs[fd.Name].(*Func); ok {
				pkgDecls[fn] = fd
			}
		}
		syntax.Inspect(d, func(n syntax.Node) bool {
			vs, ok := n.(*syntax.VarSpec)
			if !ok || len(vs.Names) != 1 || len(vs.Values) != 1 || vs.Pattern != nil {
				return true
			}
			if lit, ok := unparen(vs.Values[0]).(*syntax.FuncLit); ok {
				if v, ok := w.info.Defs[vs.Names[0]].(*Var); ok {
					localLits[v] = lit
				}
			}
			return true
		})
	}

	markParams := func(fl *syntax.FieldList, sliceSet map[int]bool, origin string) {
		if fl == nil {
			return
		}
		idx := 0
		for _, field := range fl.List {
			if len(field.Names) == 0 {
				idx++
				continue
			}
			for _, name := range field.Names {
				if sliceSet[idx] {
					if v, ok := w.info.Defs[name].(*Var); ok {
						w.scopedVars[v] = origin
					}
				}
				idx++
			}
		}
	}

	for _, d := range f.syntax.Decls {
		syntax.Inspect(d, func(n syntax.Node) bool {
			call, ok := n.(*syntax.CallExpr)
			if !ok {
				return true
			}
			k := w.info.Calls[call]
			if k == nil || k.Kind != CallFunc || k.Func == nil {
				return true
			}
			byCb := scopedCallbackMap(k.Func)
			if len(byCb) == 0 {
				return true
			}
			for cbIdx, sliceSet := range byCb {
				argIdx := cbIdx
				if k.Recv != nil && !k.RecvIsParam() {
					argIdx--
				}
				if argIdx < 0 || argIdx >= len(call.Args) {
					continue
				}
				arg := unparen(call.Args[argIdx])
				origin := fmt.Sprintf("%s callback", k.Func.Name)
				switch a := arg.(type) {
				case *syntax.FuncLit:
					if a.Type != nil {
						markParams(a.Type.Params, sliceSet, origin)
					}
				case *syntax.Ident:
					switch obj := w.info.Uses[a].(type) {
					case *Var:
						if lit := localLits[obj]; lit != nil && lit.Type != nil {
							markParams(lit.Type.Params, sliceSet, origin)
							continue
						}
					case *Func:
						if fd := pkgDecls[obj]; fd != nil && fd.Type != nil {
							markParams(fd.Type.Params, sliceSet, origin)
							continue
						}
					}
					w.c.errorf(arg, CodeType, "%s: callback for // ergo:scoped parameter must be a function literal or same-package function so the borrowed C slice can be verified not to escape", k.Func.Name)
				default:
					w.c.errorf(arg, CodeType, "%s: callback for // ergo:scoped parameter must be a function literal or same-package function so the borrowed C slice can be verified not to escape", k.Func.Name)
				}
			}
			return true
		})
	}
}

// isScopedExpr reports whether x directly names a C-borrowed scoped slice or
// is a sub-slice/parenthesization of one.
func (w *escWalk) isScopedExpr(x syntax.Expr) bool {
	if len(w.scopedVars) == 0 || x == nil {
		return false
	}
	for {
		switch e := x.(type) {
		case *syntax.ParenExpr:
			x = e.X
		case *syntax.SliceExpr:
			x = e.X
		case *syntax.Ident:
			v, ok := w.info.Uses[e].(*Var)
			return ok && w.scopedVars[v] != ""
		default:
			return false
		}
	}
}

// checkScopedSlice enforces the non-escape allow-list for C-borrowed
// `// ergo:scoped` slices and their local aliases / sub-slices.
func (w *escWalk) checkScopedSlice(n syntax.Node) {
	if w.collecting || len(w.scopedVars) == 0 {
		return
	}
	switch x := n.(type) {
	case *syntax.Ident:
		v, ok := w.info.Uses[x].(*Var)
		if !ok || w.scopedVars[v] == "" {
			return
		}
		if w.escapingFrom(v) != nil {
			w.c.errorf(x, CodeType, scopedCaptureText, x.Name)
			return
		}
		if !w.scopedSlicePlace(x, v) {
			w.c.errorf(x, CodeType, scopedEscapeText, x.Name)
		}
	case *syntax.SliceExpr:
		if !w.isScopedExpr(x.X) {
			return
		}
		if !w.scopedSlicePlace(x, nil) {
			w.c.errorf(x, CodeType, scopedEscapeText, exprText(x))
		}
	}
}

// ancestorOf returns the nearest non-ParenExpr ancestor of target on w.stack,
// together with the direct child expression of that ancestor wrapping target.
func (w *escWalk) ancestorOf(target syntax.Node) (syntax.Node, syntax.Node) {
	i := len(w.stack) - 1
	for i >= 0 && w.stack[i] != target {
		i--
	}
	if i <= 0 {
		return nil, target
	}
	child := target
	for i--; i >= 0; i-- {
		if _, ok := w.stack[i].(*syntax.ParenExpr); ok {
			child = w.stack[i]
			continue
		}
		return w.stack[i], child
	}
	return nil, child
}

// scopedSlicePlace reports whether x (a C-borrowed scoped slice expression)
// stands in an allow-listed non-escaping read-only position.
func (w *escWalk) scopedSlicePlace(x syntax.Expr, v *Var) bool {
	parent, child := w.parentOf(x)
	switch p := parent.(type) {
	case *syntax.ReturnStmt:
		return false
	case *syntax.VarSpec:
		if len(p.Names) != 1 || p.Pattern != nil || len(p.Values) != 1 || p.Values[0] != child {
			return false
		}
		if p.Names[0].Name == "_" {
			return true
		}
		dv, ok := w.info.Defs[p.Names[0]].(*Var)
		if !ok || dv.pkg {
			return false
		}
		if dv.mut {
			w.c.errorf(p.Names[0], CodeType, scopedMutText, p.Names[0].Name)
			return true
		}
		origin := "scoped slice"
		if v != nil {
			origin = w.scopedVars[v]
		}
		w.scopedVars[dv] = origin
		return true
	case *syntax.IndexExpr:
		if p.X != child {
			return false
		}
		// Reject writes through the borrowed C slice (`data[i] = b`).
		gp, gc := w.ancestorOf(p)
		if g, ok := gp.(*syntax.AssignStmt); ok {
			if slices.Contains(g.Lhs, gc.(syntax.Expr)) {
				return false
			}
		}
		return true
	case *syntax.SliceExpr:
		return p.X == child
	case *syntax.RangeStmt:
		return p.X == child
	case *syntax.SelectorExpr:
		if p.X != child {
			return false
		}
		gp, gc := w.ancestorOf(p)
		call, ok := gp.(*syntax.CallExpr)
		if !ok || call.Fun != gc {
			return false
		}
		if (p.Sel.Name == "Len" || p.Sel.Name == "Clone") && len(call.Args) == 0 {
			return true
		}
		if k := w.info.Calls[call]; k != nil && k.Kind == CallFunc && k.Recv != nil {
			return w.isScopedSafeCallArg(k, 0)
		}
		return false
	case *syntax.CallExpr:
		if p.Fun == child {
			return false
		}
		k := w.info.Calls[p]
		if k == nil {
			return true // an unchecked call has its own diagnostic
		}
		if k.Kind == CallLen {
			return true
		}
		for i, a := range p.Args {
			if a == child {
				return w.isScopedSafeCallArg(k, i)
			}
		}
		return false
	}
	return false
}

// isScopedSafeCallArg reports whether passing a `// ergo:scoped` slice as
// argument argIdx of call k is statically safe (a known clone function or a
// `// ergo:reads` non-`own` parameter).
func (w *escWalk) isScopedSafeCallArg(k *Call, argIdx int) bool {
	if k.Kind != CallFunc || k.Func == nil {
		return false
	}
	fn := k.Func
	// Ergo std `slices.Clone(data)`.
	if fn.Pkg != nil && fn.Pkg.Path == "slices" && fn.Name == "Clone" {
		return true
	}
	if fn.Decl != nil && fn.Decl.Extern != nil && fn.Decl.Extern.Target != nil {
		path, name := fn.Decl.Extern.Split()
		if (path == "slices" && name == "Clone") ||
			(path == "bytes" && name == "Clone") ||
			(path == "ergo.local/prototype/runtime/v1" && name == "SlicesClone") {
			return true
		}
	}
	// Host binding `// ergo:reads <param>` (non-`own`).
	h := hostOf(fn.Pkg)
	if h == nil || len(h.reads[fn]) == 0 {
		return false
	}
	opIdx := argIdx
	if k.Recv != nil && !k.RecvIsParam() {
		opIdx++
	}
	paramIdx := argIdx
	if k.Recv != nil && k.RecvIsParam() && fn.Decl != nil && fn.Decl.Recv != nil {
		paramIdx--
	}
	if fn.Sig != nil && paramIdx >= 0 && slices.Contains(fn.Sig.Takes, paramIdx) {
		return false
	}
	for _, name := range h.reads[fn] {
		if operandIndex(fn, name) == opIdx {
			return true
		}
	}
	return false
}
